$service=new ShippingPriceService($db);$portResolver=new PortNameResolver($db,(int)$conf->entity);$options=$service->getFilterOptions(false);$action=GETPOST('action','aZ09');$id=GETPOSTINT('id');$isPost=($_SERVER['REQUEST_METHOD']??'GET')==='POST';if($action!==''&&!$isPost)accessforbidden();

function chinaplanetsp_manual_batch($db,$conf,$user)
{
 $res=$db->query("SELECT rowid FROM ".MAIN_DB_PREFIX."chinaplanetsp_batch WHERE entity=".(int)$conf->entity." AND source_name='Manual entry' AND status=2 ORDER BY rowid DESC LIMIT 1");$batch=$res?$db->fetch_object($res):null;if($batch)return(int)$batch->rowid;
 $ref='SPB-MANUAL-'.(int)$conf->entity;$sql="INSERT INTO ".MAIN_DB_PREFIX."chinaplanetsp_batch(entity,ref,source_name,original_name,stored_file,file_hash,source_sheet,effective_date,import_mode,ignore_below,currency_code,total_rows,accepted_rows,ignored_rows,warning_count,status,report_json,fk_user_creat,date_creation) VALUES(".(int)$conf->entity.",'".$db->escape($ref)."','Manual entry','Manual rates manager',NULL,'".hash('sha256',$ref)."','MANUAL','".date('Y-m-d')."','manual',".price2num((float)($conf->global->CHINAPLANETSP_IGNORE_BELOW??1000)).",'USD',0,0,0,0,2,'{}',".(int)$user->id.",'".$db->idate(dol_now())."')";
 if(!$db->query($sql))throw new RuntimeException($db->lasterror());return(int)$db->last_insert_id(MAIN_DB_PREFIX.'chinaplanetsp_batch');
}

if($action==='disable'&&$id>0){if($db->query("UPDATE ".MAIN_DB_PREFIX."chinaplanetsp_rate SET status=0,is_current=0 WHERE rowid=".$id." AND entity=".(int)$conf->entity))setEventMessages('Price disabled. It remains available in history.',null,'mesgs');}
if($action==='save'){
 $pol=trim(GETPOST('pol','alphanohtml'));$country=strtoupper(trim(GETPOST('country_code','alpha')));$podRaw=trim(GETPOST('pod','alphanohtml'));$line=trim(GETPOST('shipping_line','alphanohtml'));$container=strtoupper(trim(GETPOST('container_type','alphanohtml')));$serviceType=strtolower(trim(GETPOST('service_type','alpha')));$cost=(float)GETPOST('cost_price','alphanohtml');$sale=(float)GETPOST('sale_price','alphanohtml');$currency=strtoupper(trim(GETPOST('currency_code','alpha'))?:'USD');$validFrom=GETPOST('valid_from','alpha')?:date('Y-m-d');$validTo=GETPOST('valid_to','alpha')?:date('Y-m-d',strtotime($validFrom.' +30 days'));$publicVisible=GETPOSTINT('public_visible')?1:0;$publicNotes=GETPOST('public_notes','restricthtml');$internalNotes=GETPOST('internal_notes','restricthtml');$threshold=(float)($conf->global->CHINAPLANETSP_IGNORE_BELOW??1000);$resolved=$portResolver->resolveList($podRaw,true);$portMatch=$resolved['status']==='matched'&&count($resolved['matches'])===1?$resolved['matches'][0]:null;$pod=$portMatch?$portMatch['port_name']:$podRaw;
 if($pol===''||$pod===''||$line===''||$container===''||!preg_match('/^[A-Z]{2}$/',$country)||!in_array($serviceType,array('direct','transit','unknown'),true))setEventMessages('POL, country, POD, shipping line, container and service are required.',null,'errors');
 elseif(!$portMatch)setEventMessages('POD must match one canonical port. Add or correct its alias in Ports & countries first.',null,'errors');
 elseif($country!==$portMatch['country_code'])setEventMessages('Selected country does not match the canonical port country ('.$portMatch['country_code'].').',null,'errors');
 elseif($cost<$threshold||$sale<=0)setEventMessages('Supplier cost must be at least '.price($threshold).' and sale price must be greater than zero.',null,'errors');
 elseif(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$validFrom)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$validTo)||$validTo<$validFrom)setEventMessages('Valid to must be on or after Valid from.',null,'errors');
 else{
  try{$manualBatch=chinaplanetsp_manual_batch($db,$conf,$user);$db->begin();$existing=null;if($id>0){$res=$db->query("SELECT r.*,b.source_name FROM ".MAIN_DB_PREFIX."chinaplanetsp_rate r JOIN ".MAIN_DB_PREFIX."chinaplanetsp_batch b ON b.rowid=r.fk_batch WHERE r.rowid=".$id." AND r.entity=".(int)$conf->entity);$existing=$res?$db->fetch_object($res):null;if(!$existing)throw new RuntimeException('Price not found.');}
   if(!$existing){$dupSql="SELECT rowid FROM ".MAIN_DB_PREFIX."chinaplanetsp_rate WHERE entity=".(int)$conf->entity." AND status=1 AND is_current=1 AND pol='".$db->escape($pol)."' AND destination_country='".$db->escape($country)."' AND pod='".$db->escape($pod)."' AND shipping_line='".$db->escape($line)."' AND container_type='".$db->escape($container)."' AND service_type='".$db->escape($serviceType)."' LIMIT 1";$dup=$db->query($dupSql);if($dup&&$db->num_rows($dup))throw new RuntimeException('This exact route already exists. Search for it and use Edit.');}
   $assign="pol='".$db->escape($pol)."',destination_country='".$db->escape($portMatch['country_code'])."',pod='".$db->escape($pod)."',pod_raw='".$db->escape($podRaw)."',fk_destination_port=".((int)($portMatch['fk_port']??0)>0?(int)$portMatch['fk_port']:'NULL').",port_match_method='".$db->escape($portMatch['method']??$resolved['method']??'exact')."',port_match_score=".number_format((float)($portMatch['score']??$resolved['score']??1),4,'.','').",shipping_line='".$db->escape($line)."',service_type='".$db->escape($serviceType)."',route_detail=".($serviceType==='direct'?"'DIRECT'":"'TRANSIT'").",container_type='".$db->escape($container)."',cost_price=".price2num($cost).",sale_price=".price2num($sale).",currency_code='".$db->escape($currency)."',valid_from='".$db->escape($validFrom)."',valid_to='".$db->escape($validTo)."',public_notes='".$db->escape($publicNotes)."',internal_notes='".$db->escape($internalNotes)."',public_visible=".$publicVisible.",is_current=1,status=1";
   if($existing&&$existing->source_name==='Manual entry')$sql="UPDATE ".MAIN_DB_PREFIX."chinaplanetsp_rate SET ".$assign." WHERE rowid=".$id." AND entity=".(int)$conf->entity;
   else{$sql="INSERT INTO ".MAIN_DB_PREFIX."chinaplanetsp_rate SET entity=".(int)$conf->entity.",fk_batch=".$manualBatch.",source_sheet='MANUAL',source_row=0,source_cell=NULL,region_label='Manual entry',".$assign.",fk_user_creat=".(int)$user->id.",date_creation='".$db->idate(dol_now())."'";if($existing&&!$db->query("UPDATE ".MAIN_DB_PREFIX."chinaplanetsp_rate SET status=0,is_current=0 WHERE rowid=".$id." AND entity=".(int)$conf->entity))throw new RuntimeException($db->lasterror());}
   if(!$db->query($sql))throw new RuntimeException($db->lasterror());
   $db->commit();setEventMessages($existing?'Price updated. Original imported record was preserved in history.':'New manual price added.',null,'mesgs');$id=0;
  }catch(Throwable$e){$db->rollback();setEventMessages($e->getMessage(),null,'errors');}
 }
}

$editId=GETPOSTINT('edit');$edit=null;if($editId){$res=$db->query("SELECT r.*,b.source_name FROM ".MAIN_DB_PREFIX."chinaplanetsp_rate r JOIN ".MAIN_DB_PREFIX."chinaplanetsp_batch b ON b.rowid=r.fk_batch WHERE r.rowid=".$editId." AND r.entity=".(int)$conf->entity);$edit=$res?$db->fetch_object($res):null;}
$countries=array();$res=$db->query("SELECT code,label FROM ".MAIN_DB_PREFIX."c_country WHERE active=1 ORDER BY label");if($res)while($c=$db->fetch_object($res))$countries[$c->code]=$c->label;
$show=GETPOSTINT('show')===1;$filters=array('country'=>strtoupper(GETPOST('filter_country','alpha')),'pod'=>GETPOST('filter_pod','alphanohtml'),'pol'=>GETPOST('filter_pol','alphanohtml'),'line'=>GETPOST('filter_line','alphanohtml'),'container'=>strtoupper(GETPOST('filter_container','alphanohtml')),'status'=>GETPOST('filter_status','alpha'));
$rows=array();if($show){$sql="SELECT r.*,b.source_name,b.original_name FROM ".MAIN_DB_PREFIX."chinaplanetsp_rate r JOIN ".MAIN_DB_PREFIX."chinaplanetsp_batch b ON b.rowid=r.fk_batch WHERE r.entity=".(int)$conf->entity;if($filters['country']!=='')$sql.=" AND r.destination_country='".$db->escape($filters['country'])."'";foreach(array('pod'=>'pod','pol'=>'pol','line'=>'shipping_line','container'=>'container_type')as$k=>$field)if($filters[$k]!=='')$sql.=" AND r.".$field."='".$db->escape($filters[$k])."'";if($filters['status']==='inactive')$sql.=" AND (r.status=0 OR r.is_current=0)";elseif($filters['status']!=='all')$sql.=" AND r.status=1 AND r.is_current=1";$sql.=" ORDER BY r.status DESC,r.is_current DESC,r.pod,r.container_type,r.sale_price LIMIT 250";$res=$db->query($sql);if($res)while($row=$db->fetch_object($res))$rows[]=$row;}
$css=array(cpcc_admin_shell_asset('/custom/chinaplanetcustomercenter/css/admin_dashboard.css'),cpcc_admin_shell_asset('/custom/chinaplanetshippingprices/css/shippingprices.css'));
llxHeader('','Shipping Rates Manager','','',0,0,array(),$css);cpcc_admin_shell_open('shippingprices','Shipping rates manager / إدارة أسعار الشحن','ابحث أولاً، ثم أضف أو عدّل أو عطّل السعر المطلوب','fa-table');
if(GETPOSTINT('add')||$edit){$validToForForm=$edit&&!empty($edit->valid_to)?$edit->valid_to:date('Y-m-d',strtotime('+30 days'));print '<script>document.addEventListener("DOMContentLoaded",function(){var from=document.querySelector("input[name=valid_from]");if(!from||document.querySelector("input[name=valid_to]"))return;var label=document.createElement("label"),span=document.createElement("span"),input=document.createElement("input");span.textContent="Valid to *";input.type="date";input.name="valid_to";input.required=true;input.value="'.dol_escape_js($validToForForm).'";label.append(span,input);from.closest("label").after(label);});</script>';}
print '<main class="chinaplanetsp-rates-manager"><div class="chinaplanetsp-admin-toolbar"><a class="button" href="dashboard.php">Control center</a><a class="button" href="../index.php">Price inquiry</a><a class="button" href="disabled.php"><span class="fas fa-ban"></span> Disabled prices</a><a class="button button-save" href="?add=1">+ Add new price</a></div>';
print '<section class="chinaplanetsp-rate-filter"><h2>Find prices / البحث عن الأسعار</h2><form method="get"><input type="hidden" name="show" value="1"><div class="chinaplanetsp-rule-grid">';
$filterSelect=function($name,$label,$values,$selected,$all){print '<label><span>'.$label.'</span><select name="'.$name.'"><option value="">'.$all.'</option>';foreach($values as$key=>$text){$value=is_int($key)?$text:$key;print '<option value="'.dol_escape_htmltag($value).'"'.($selected===$value?' selected':'').'>'.dol_escape_htmltag($text).'</option>';}print '</select></label>';};
$filterSelect('filter_country','Country',$options['countries'],$filters['country'],'All countries');$filterSelect('filter_pod','POD',$options['pod'],$filters['pod'],'All PODs');$filterSelect('filter_pol','POL',$options['pol'],$filters['pol'],'All POLs');$filterSelect('filter_line','Shipping line',$options['lines'],$filters['line'],'All lines');$filterSelect('filter_container','Container',$options['containers'],$filters['container'],'All containers');print '<label><span>Status</span><select name="filter_status"><option value="current">Current</option><option value="inactive"'.($filters['status']==='inactive'?' selected':'').'>Disabled / historical</option><option value="all"'.($filters['status']==='all'?' selected':'').'>All</option></select></label></div><div class="chinaplanetsp-rule-actions"><button class="button button-save"><span class="fas fa-search"></span> Show prices</button></div></form></section>';
if(GETPOSTINT('add')||$edit){$v=function($field,$default='')use($edit){return dol_escape_htmltag($edit&&isset($edit->$field)?$edit->$field:$default);};print '<section class="chinaplanetsp-rule-editor"><h2>'.($edit?'Edit price #'.(int)$edit->rowid:'Add new shipping price').'</h2>'.($edit&&$edit->source_name!=='Manual entry'?'<div class="info">This price came from '.$edit->source_name.'. Saving creates a manual replacement and preserves the original in history.</div>':'').'<form method="post"><input type="hidden" name="token" value="'.newToken().'"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="'.($edit?(int)$edit->rowid:0).'"><div class="chinaplanetsp-rule-grid"><label><span>POL *</span><input name="pol" required list="rate-pols" value="'.$v('pol').'" placeholder="Shanghai"></label><label><span>Destination country *</span><select name="country_code" required><option value="">Select country</option>';foreach($countries as$code=>$name)print '<option value="'.$code.'"'.($edit&&$edit->destination_country===$code?' selected':'').'>'.dol_escape_htmltag($name).' ('.$code.')</option>';print '</select></label><label><span>POD *</span><input name="pod" required list="rate-pods" value="'.$v('pod').'" placeholder="SOKHNA"></label><label><span>Shipping line *</span><input name="shipping_line" required list="rate-lines" value="'.$v('shipping_line').'" placeholder="PIL"></label><label><span>Container *</span><input name="container_type" required list="rate-containers" value="'.$v('container_type','20GP').'" placeholder="20GP"></label><label><span>Service *</span><select name="service_type"><option value="direct"'.(!$edit||$edit->service_type==='direct'?' selected':'').'>Direct</option><option value="transit"'.($edit&&$edit->service_type==='transit'?' selected':'').'>Transit</option><option value="unknown"'.($edit&&$edit->service_type==='unknown'?' selected':'').'>Unknown</option></select></label><label><span>Supplier cost *</span><input name="cost_price" required inputmode="decimal" value="'.$v('cost_price').'" placeholder="3200"></label><label><span>Sale price *</span><input name="sale_price" required inputmode="decimal" value="'.$v('sale_price').'" placeholder="3600"></label><label><span>Currency</span><input name="currency_code" maxlength="3" value="'.$v('currency_code','USD').'"></label><label><span>Valid from</span><input type="date" name="valid_from" value="'.$v('valid_from',date('Y-m-d')).'"></label><label class="chinaplanetsp-rule-check"><input type="checkbox" name="public_visible" value="1"'.(!$edit||(int)$edit->public_visible?' checked':'').'><span>Visible to customers</span></label><label class="chinaplanetsp-rule-note"><span>Customer-visible note</span><textarea name="public_notes" rows="3">'.$v('public_notes').'</textarea></label><label class="chinaplanetsp-rule-note"><span>Internal note</span><textarea name="internal_notes" rows="3">'.$v('internal_notes').'</textarea></label></div><div class="chinaplanetsp-rule-actions"><button class="button button-save">'.($edit?'Save replacement':'Add price').'</button><a class="button" href="adjust.php">Cancel</a></div><datalist id="rate-pols">';foreach($options['pol']as$x)print'<option value="'.dol_escape_htmltag($x).'">';print'</datalist><datalist id="rate-pods">';foreach($options['pod']as$x)print'<option value="'.dol_escape_htmltag($x).'">';print'</datalist><datalist id="rate-lines">';foreach($options['lines']as$x)print'<option value="'.dol_escape_htmltag($x).'">';print'</datalist><datalist id="rate-containers">';foreach($options['containers']as$x)print'<option value="'.dol_escape_htmltag($x).'">';print'</datalist></form></section>';}
if($show){print '<section class="chinaplanetsp-rule-list"><div class="chinaplanetsp-list-head"><h2>Prices found <span>'.count($rows).'</span></h2><a class="button button-save" href="?add=1">+ Add new price</a></div><div class="div-table-responsive"><table class="noborder centpercent"><tr class="liste_titre"><th>Route</th><th>Line / trade lane</th><th>Container</th><th class="right">Cost</th><th class="right">Sale</th><th class="right">Margin</th><th>Source</th><th>Status</th><th>Actions</th></tr>';foreach($rows as$r){$active=(int)$r->status===1&&(int)$r->is_current===1;print '<tr><td><strong>'.dol_escape_htmltag($r->pol.' → '.$r->pod).'</strong><small>'.dol_escape_htmltag($countries[$r->destination_country]??$r->destination_country).' · '.dol_escape_htmltag($r->valid_from).'</small></td><td>'.dol_escape_htmltag($r->shipping_line).'<small>'.dol_escape_htmltag(($r->region_label?$r->region_label.' · ':'').ucfirst($r->service_type)).'</small></td><td>'.dol_escape_htmltag($r->container_type).'</td><td class="right">'.price($r->cost_price).' '.$r->currency_code.'</td><td class="right"><strong>'.price($r->sale_price).' '.$r->currency_code.'</strong></td><td class="right">'.price($r->sale_price-$r->cost_price).'</td><td>'.dol_escape_htmltag($r->source_name).'<small>'.dol_escape_htmltag($r->source_sheet.' row '.$r->source_row).'</small></td><td>'.($active?'Current':'Disabled').'</td><td class="chinaplanetsp-row-actions"><a class="button smallpaddingimp" href="?edit='.(int)$r->rowid.'">Edit</a>'.($active?'<form method="post" onsubmit="return confirm(\'Disable this price? It will remain in history.\')"><input type="hidden" name="token" value="'.newToken().'"><input type="hidden" name="action" value="disable"><input type="hidden" name="id" value="'.(int)$r->rowid.'"><button class="button button-delete smallpaddingimp">Delete / disable</button></form>':'').'</td></tr>';}print '</table></div></section>';}
